// ==========================================
// FORMATADOR: PEDIDO ASSINADO
// ==========================================

const formatCurrency = (value) => {
  if (!value) return 'R$ 0,00';
  const numericValue = typeof value === 'string' ? parseFloat(value) : value;
  return new Intl.NumberFormat('pt-BR', { 
    style: 'currency', 
    currency: 'BRL' 
  }).format(numericValue);
};

const formatDate = (dateString) => {
  if (!dateString) return 'Data não disponível';
  return new Date(dateString).toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

const data = $json.body.data;

// Formatar produtos
let produtosTexto = '';
data.products.forEach((product, index) => {
  const num = index + 1;
  const nome = product.name || 'Produto sem nome';
  const sku = product.sku ? ` (${product.sku})` : '';
  const quantidade = product.quantity || 0;
  const preco = formatCurrency(product.price);
  const subtotal = formatCurrency(product.subtotal);

  // Atributos especiais (NOVOS CAMPOS)
  let atributosExtras = [];
  if (product.modelo) atributosExtras.push(`📐 Modelo: ${product.modelo}`);
  if (product.paperType) atributosExtras.push(`📄 Papel: ${product.paperType}`);
  if (product.lamination) atributosExtras.push(`✨ Laminação: ${product.lamination}`);

  // Atributos genéricos
  const atributosGenericos = Object.entries(product.attributes || {})
    .filter(([key]) => !['Papel', 'PAPEL', 'papel'].includes(key))
    .map(([key, value]) => `${key}: ${value}`)
    .join(' | ');

  // Acabamentos
  const finishing = product.finishing || {};
  const acabamentos = [];
  if (finishing.hotStamp) acabamentos.push('🔥 Hot Stamp' + (finishing.hotStampCor && finishing.hotStampCor !== 'nenhum' ? ` (${finishing.hotStampCor})` : ''));
  if (finishing.eyelets) acabamentos.push('👁️ Ilhós');
  if (finishing.furoPresente) acabamentos.push('🎁 Furo Presente');
  if (finishing.cord || (finishing.cordao && finishing.cordao !== 'nenhum')) {
    const cordaoTipo = finishing.cordao || 'padrão';
    const cordaoCor = finishing.corCordao && finishing.corCordao !== 'nenhum' ? ` - ${finishing.corCordao}` : '';
    acabamentos.push(`🎀 Cordão: ${cordaoTipo}${cordaoCor}`);
  }

  produtosTexto += `\n*${num}.* ${nome}${sku}\n`;
  produtosTexto += `   📊 Quantidade: ${quantidade} un\n`;
  produtosTexto += `   💰 Preço unit: ${preco}\n`;

  if (atributosExtras.length > 0) {
    produtosTexto += `   ${atributosExtras.join('\n   ')}\n`;
  }

  if (atributosGenericos) {
    produtosTexto += `   📝 ${atributosGenericos}\n`;
  }

  if (acabamentos.length > 0) {
    produtosTexto += `   🔧 Acabamentos: ${acabamentos.join(', ')}\n`;
  }

  produtosTexto += `   💵 *Subtotal: ${subtotal}*\n`;
  produtosTexto += `-------------------------------------------\n`;
});

// Dados do cliente
const clienteNome = data.customerName || 'Cliente não informado';
const clienteEmail = data.customerEmail || 'Não informado';
const clienteTelefone = data.customerPhone || 'Não informado';
const clienteEmpresa = data.customerCompany || '';
const clienteCpf = data.customerCpf || '';
const clienteCnpj = data.customerCnpj || '';

// Endereço
const endereco = [];
if (data.customerAddress) endereco.push(data.customerAddress);
if (data.customerNumber) endereco.push(`, ${data.customerNumber}`);
if (data.customerComplement) endereco.push(` - ${data.customerComplement}`);
if (data.customerNeighborhood) endereco.push(`\n   Bairro: ${data.customerNeighborhood}`);
if (data.customerCity && data.customerState) endereco.push(`\n   ${data.customerCity}/${data.customerState}`);
if (data.customerCep) endereco.push(`\n   CEP: ${data.customerCep}`);

// Montar mensagem
let mensagem = `✅ *NOVO PEDIDO ASSINADO* ✅\n`;
mensagem += `═══════════════════════════════════════\n\n`;

mensagem += `📋 *COTAÇÃO:* ${data.quoteNumber || 'N/A'}\n`;
mensagem += `📅 *Data:* ${formatDate(data.signedAt || new Date())}\n`;
mensagem += `✅ Status: Assinado pelo cliente\n\n`;

mensagem += `👤 *DADOS DO CLIENTE*\n`;
mensagem += `───────────────────────────────────────\n`;
mensagem += `Nome: ${clienteNome}\n`;
if (clienteEmpresa) mensagem += `Empresa: ${clienteEmpresa}\n`;
if (clienteCpf) mensagem += `CPF: ${clienteCpf}\n`;
if (clienteCnpj) mensagem += `CNPJ: ${clienteCnpj}\n`;
mensagem += `Email: ${clienteEmail}\n`;
mensagem += `Telefone: ${clienteTelefone}\n`;
if (endereco.length > 0) mensagem += `📍 Endereço: ${endereco.join('')}\n`;
mensagem += `\n`;

mensagem += `📦 *PRODUTOS DO PEDIDO*\n`;
mensagem += `═══════════════════════════════════════\n`;
mensagem += produtosTexto;
mensagem += `\n`;

mensagem += `💰 *TOTAL DO PEDIDO*\n`;
mensagem += `═══════════════════════════════════════\n`;
mensagem += `*${formatCurrency(data.totalPrice)}*\n\n`;

if (data.condicoesPagamento) {
  mensagem += `💳 *FORMA DE PAGAMENTO*\n`;
  mensagem += `───────────────────────────────────────\n`;
  const pagamento = typeof data.condicoesPagamento === 'object' 
    ? JSON.stringify(data.condicoesPagamento, null, 2) 
    : data.condicoesPagamento;
  mensagem += `${pagamento}\n\n`;
}

if (data.createdByName) {
  mensagem += `👨‍💼 *VENDEDOR:* ${data.createdByName}\n\n`;
}

mensagem += `═══════════════════════════════════════\n`;
mensagem += `_Sistema Embraflex - ${formatDate(new Date())}_`;

return {
  json: {
    mensagem: mensagem,
    tipo: 'assinado',
    quoteNumber: data.quoteNumber,
    customerName: clienteNome,
    totalPrice: data.totalPrice
  }
};

// ==========================================
// FORMATADOR: COTAÇÃO REJEITADA
// ==========================================

const formatDate = (dateString) => {
  if (!dateString) return 'Data não disponível';
  return new Date(dateString).toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

const data = $json.body.data;

// Resumo dos produtos
const produtosResumo = data.products.map((p, i) => `${i + 1}. ${p.name} (${p.quantity}un)`).join('\n');

let mensagem = `❌ *COTAÇÃO RECUSADA* ❌\n`;
mensagem += `═══════════════════════════════════════\n\n`;

mensagem += `📋 *COTAÇÃO:* ${data.quoteNumber || 'N/A'}\n`;
mensagem += `📅 *Data:* ${formatDate(data.rejectedAt || new Date())}\n`;
mensagem += `❌ Status: Recusada pelo cliente\n\n`;

mensagem += `👤 *CLIENTE:* ${data.customerName || 'Não informado'}\n`;
mensagem += `📞 *TELEFONE:* ${data.customerPhone || 'Não informado'}\n\n`;

mensagem += `📦 *PRODUTOS:*\n`;
mensagem += produtosResumo;
mensagem += `\n\n`;

mensagem += `💰 *TOTAL:* R$ ${data.totalPrice}\n\n`;

if (data.rejectionReason) {
  mensagem += `📝 *MOTIVO DA RECUSA:*\n`;
  mensagem += `${data.rejectionReason}\n\n`;
} else {
  mensagem += `📝 *Motivo não informado*\n\n`;
}

if (data.createdByName) {
  mensagem += `👨‍💼 *VENDEDOR:* ${data.createdByName}\n\n`;
}

mensagem += `⚠️ Entrar em contato com o cliente para entender o motivo.\n`;
mensagem += `═══════════════════════════════════════\n`;
mensagem += `_Sistema Embraflex - ${formatDate(new Date())}_`;

return {
  json: {
    mensagem: mensagem,
    tipo: 'rejeitado',
    quoteNumber: data.quoteNumber,
    customerName: data.customerName
  }
};

// ==========================================
// FORMATADOR: PEDIDO CRIADO
// ==========================================

const formatCurrency = (value) => {
  if (!value) return 'R$ 0,00';
  const numericValue = typeof value === 'string' ? parseFloat(value) : value;
  return new Intl.NumberFormat('pt-BR', { 
    style: 'currency', 
    currency: 'BRL' 
  }).format(numericValue);
};

const formatDate = (dateString) => {
  if (!dateString) return 'Data não disponível';
  return new Date(dateString).toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

const data = $json.body.data;

let mensagem = `📦 *PEDIDO CRIADO NO WOOCOMMERCE* 📦\n`;
mensagem += `═══════════════════════════════════════\n\n`;

mensagem += `📋 *PEDIDO:* ${data.orderNumber || 'N/A'}\n`;
mensagem += `📅 *Data:* ${formatDate(new Date())}\n\n`;

mensagem += `👤 *CLIENTE:* ${data.customerName || 'Não informado'}\n`;
mensagem += `📧 *EMAIL:* ${data.customerEmail || 'Não informado'}\n\n`;

mensagem += `📦 *PRODUTOS:* ${data.products.length} itens\n`;
mensagem += `💰 *TOTAL:* ${formatCurrency(data.totalPrice)}\n\n`;

if (data.paymentUrl) {
  mensagem += `🔗 *LINK DE PAGAMENTO:*\n`;
  mensagem += `${data.paymentUrl}\n\n`;
}

mensagem += `═══════════════════════════════════════\n`;
mensagem += `_Sistema Embraflex - ${formatDate(new Date())}_`;

return {
  json: {
    mensagem: mensagem,
    tipo: 'pedido_criado',
    orderNumber: data.orderNumber,
    customerName: data.customerName
  }
};

// Evento não reconhecido
return {
  json: {
    mensagem: `⚠️ Evento recebido: ${$json.body.event}\nNenhuma ação configurada para este evento.`,
    tipo: 'desconhecido'
  }
};

// Preparar resposta de sucesso
return {
  json: {
    status: 'success',
    message: 'Notificação processada',
    event: $json.body.event,
    quoteNumber: $json.body.data?.quoteNumber,
    timestamp: new Date().toISOString()
  }
};
